fun parts(index: Index): Flow<ByteArray> = flow {   // cold: no work on creation
    for (range in index.ranges) emit(fetchPart(range))   // suspends, cancellable
}.flowOn(Dispatchers.IO)                            // stage runs off the caller

scope.launch { parts(index).take(4).collect { sink.write(it) } }
